from pycompss.api.task import task
from pycompss.api.api import compss_wait_on

# --- 1. The Serial Logic (Helper) ---
def serial_convex_hull(points):
    """ Standard Monotone Chain algorithm (same as before). """
    points = sorted(points) # Ensure sorted
    if len(points) <= 2: return points

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)

    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)

    return lower[:-1] + upper[:-1]

# --- 2. The PyCOMPSs Tasks ---

@task(returns=list)
def compute_local_hull(chunk):
    """ Calculates the hull for a subset of data. """
    return serial_convex_hull(chunk)

@task(returns=list)
def merge_hulls(hull_a, hull_b):
    """ 
    Naive Merge: Combine two hulls and solve again.
    This works because Hull(A U B) == Hull(Hull(A) U Hull(B))
    """
    combined = hull_a + hull_b
    return serial_convex_hull(combined)

# --- 3. The Orchestrator ---

def main(points, chunk_size=2):
    # 1. Chunking
    chunks = [points[i:i + chunk_size] for i in range(0, len(points), chunk_size)]

    # 2. Map Phase: Compute local hulls
    # 'working_list' will hold Future objects
    working_list = [compute_local_hull(chunk) for chunk in chunks]

    # 3. Reduce Phase: Tree Reduction
    while len(working_list) > 1:
        new_level = []
        for i in range(0, len(working_list), 2):
            if i + 1 < len(working_list):
                # Merge pair
                merged = merge_hulls(working_list[i], working_list[i+1])
                new_level.append(merged)
            else:
                # Carry over odd one out
                new_level.append(working_list[i])
        working_list = new_level

    # Wait for the final result
    return compss_wait_on(working_list[0])
